package com.emp.ems;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:ems;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false","ems.jwt-secret=dGVzdC1vbmx5LWtleS1uZXZlci11c2UtaW4tcHJvZHVjdGlvbi1mb3JtYQ==","spring.profiles.active=test"})@AutoConfigureMockMvc
class ApiIntegrationTest{@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired EmployeeRepository employees;@Autowired PasswordEncoder encoder;@Autowired JwtService jwt;@Autowired AttendanceRepository attendance;@Autowired LeaveRepository leaves;@Autowired TaskRepository tasks;@Autowired ActivityRepository activity;Employee admin,employee,other;String adminToken,token;
 @BeforeEach void setup(){activity.deleteAll();attendance.deleteAll();leaves.deleteAll();tasks.deleteAll();employees.deleteAll();admin=person("Admin","admin@test.example","ADMIN");employee=person("Employee","employee@test.example","EMPLOYEE");other=person("Other","other@test.example","EMPLOYEE");adminToken=jwt.issue(admin);token=jwt.issue(employee);}
 Employee person(String name,String email,String role){Employee e=new Employee();e.name=name;e.email=email;e.role=role;e.title="Engineer";e.department="Engineering";e.passwordHash=encoder.encode("test-password-123");return employees.save(e);}MockHttpServletRequestBuilder auth(MockHttpServletRequestBuilder r,String token){return r.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON);}
 @Test void loginAndLogoutDoNotLeakOrRetainCredentials()throws Exception{var r=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"employee@test.example\",\"password\":\"test-password-123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.employee.passwordHash").doesNotExist()).andReturn();String issued=json.readTree(r.getResponse().getContentAsString()).get("token").asText();mvc.perform(auth(post("/api/v1/auth/logout"),issued)).andExpect(status().isNoContent());mvc.perform(auth(get("/api/v1/auth/me"),issued)).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"employee@test.example\",\"password\":\"incorrect\"}")).andExpect(status().isUnauthorized());}
 @Test void roleOwnershipAndPaginationAreEnforced()throws Exception{mvc.perform(get("/api/v1/admin/employees")).andExpect(status().isUnauthorized());mvc.perform(auth(get("/api/v1/admin/employees"),token)).andExpect(status().isForbidden());mvc.perform(auth(get("/api/v1/admin/employees?size=10000"),adminToken)).andExpect(status().isOk()).andExpect(jsonPath("$.size").value(100)).andExpect(jsonPath("$.content[0].passwordHash").doesNotExist());OnboardingTask t=new OnboardingTask();t.employee=other;t.label="Private task";tasks.save(t);mvc.perform(auth(patch("/api/v1/employee/tasks/"+t.id),token).content("{\"done\":true}")).andExpect(status().isForbidden());mvc.perform(auth(patch("/api/v1/admin/tasks/"+t.id),adminToken).content("{\"done\":true}")).andExpect(status().isOk()).andExpect(jsonPath("$.done").value(true));}
 @Test void concurrentClockInsCreateExactlyOneShift()throws Exception{try(ExecutorService ex=Executors.newFixedThreadPool(2)){Callable<Integer> request=()->mvc.perform(auth(post("/api/v1/employee/attendance/clock-in"),token)).andReturn().getResponse().getStatus();var r=ex.invokeAll(List.of(request,request));assertThat(List.of(r.get(0).get(),r.get(1).get())).containsExactlyInAnyOrder(201,409);}assertThat(attendance.count()).isEqualTo(1);mvc.perform(auth(post("/api/v1/employee/attendance/clock-out"),token)).andExpect(status().isOk()).andExpect(jsonPath("$.clockOut").isNotEmpty());mvc.perform(auth(post("/api/v1/employee/attendance/clock-out"),token)).andExpect(status().isConflict());mvc.perform(auth(get("/api/v1/employee/attendance/current"),token)).andExpect(status().isNoContent());}
 @Test void leaveRangesOverlapsAndApprovalsAreValidated()throws Exception{mvc.perform(auth(post("/api/v1/employee/leaves"),token).content("{\"type\":\"Vacation\",\"startDate\":\"2027-02-10\",\"endDate\":\"2027-02-01\"}")).andExpect(status().isBadRequest());String body="{\"type\":\"Vacation\",\"startDate\":\"2027-02-01\",\"endDate\":\"2027-02-05\",\"employeeId\":\""+other.id+"\"}";var r=mvc.perform(auth(post("/api/v1/employee/leaves"),token).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.employeeId").value(employee.id.toString())).andReturn();mvc.perform(auth(post("/api/v1/employee/leaves"),token).content(body)).andExpect(status().isConflict());String id=json.readTree(r.getResponse().getContentAsString()).get("id").asText();mvc.perform(auth(patch("/api/v1/admin/leaves/"+id),adminToken).content("{\"status\":\"Approved\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("Approved"));mvc.perform(auth(patch("/api/v1/admin/leaves/"+id),adminToken).content("{\"status\":\"Rejected\"}")).andExpect(status().isConflict());}
 @Test void telemetryIsIdempotentAndContainedInWorkHours()throws Exception{Map<String,Object>d=new HashMap<>(Map.of("batchId",UUID.randomUUID(),"startedAt",Instant.now().minusSeconds(300).toString(),"endedAt",Instant.now().toString(),"keyboardEvents",20,"mouseEvents",14,"idleSeconds",50));mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isConflict());Attendance shift=new Attendance();shift.employee=employee;shift.clockIn=Instant.now().minusSeconds(400);shift.logDate=java.time.LocalDate.now();attendance.save(shift);mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isAccepted()).andExpect(jsonPath("$.status").value("accepted"));mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isAccepted()).andExpect(jsonPath("$.status").value("duplicate"));assertThat(activity.count()).isEqualTo(1);d.put("batchId",UUID.randomUUID());d.put("keyboardEvents",-1);mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isBadRequest());d.put("keyboardEvents",1);d.put("screenshotUrl","https://untrusted.example/image.jpg");mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isBadRequest());d.remove("screenshotUrl");d.put("startedAt",Instant.now().minusSeconds(1000).toString());mvc.perform(auth(post("/api/v1/employee/telemetry"),token).content(json.writeValueAsString(d))).andExpect(status().isConflict());}
 @Test void employeeCreationSeedsTasksAndRejectsDuplicateEmails()throws Exception{String body="{\"name\":\"Alex Morgan\",\"email\":\"alex@test.example\",\"title\":\"Designer\",\"department\":\"Design\",\"password\":\"a-long-test-password\"}";mvc.perform(auth(post("/api/v1/admin/employees"),adminToken).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("Onboarding"));assertThat(tasks.count()).isEqualTo(10);mvc.perform(auth(post("/api/v1/admin/employees"),adminToken).content(body)).andExpect(status().isConflict());}
 @Test void invalidJwtAndUnconfiguredStorageFailSafely()throws Exception{mvc.perform(auth(get("/api/v1/auth/me"),"invalid")).andExpect(status().isUnauthorized());mvc.perform(auth(post("/api/v1/employee/assets/upload-url"),token)).andExpect(status().isServiceUnavailable());}
}
